correctedCode:
#include <stdio.h>

#define MAX 3

int stack[MAX];
int top = -1;

void push(int value) {
    if (top == MAX - 1) {
        printf("Stack overflow, cannot push %d\n", value);
        return;
    }
    stack[++top] = value;
}

int main() {
    push(1);
    push(2);
    push(3);
    push(4);
    printf("%d\n", stack[top]);
    return 0;
}
